import{_ as e,o as t,c,ag as o}from"./chunks/framework.DyxC4IQh.js";const m=JSON.parse('{"title":"键位总览","description":"默认键位表：触发键、方向键、标签字母、退出键与点击键，以及哪些可以改。","frontmatter":{"description":"默认键位表：触发键、方向键、标签字母、退出键与点击键，以及哪些可以改。"},"headers":[],"relativePath":"guide/keys.md","filePath":"guide/keys.md","lastUpdated":1792585006000}'),a={name:"guide/keys.md"};function i(r,d,n,h,p,s){return t(),c("div",null,[...d[0]||(d[0]=[o('<h1 id="键位总览" tabindex="-1">键位总览 <a class="header-anchor" href="#键位总览" aria-label="Permalink to &quot;键位总览&quot;">​</a></h1><p>默认键位。<code>WASD</code> / <code>HJKL</code> 与三个功能键（触发键、通知键、光标点击键）可以在<a href="/vimact-site/guide/settings.html">应用设置</a>里调整，其余按键在 v0.1 中写死。</p><table tabindex="0"><thead><tr><th>键</th><th>生效场景</th><th>行为</th></tr></thead><tbody><tr><td>触发键（默认 <code>F</code>）</td><td>任意 App，非 hint 模式</td><td>进入 hint 模式，屏幕上出现标签</td></tr><tr><td>触发键</td><td>hint 模式内</td><td>退出 hint 模式，不产生点击</td></tr><tr><td><code>a</code>–<code>z</code></td><td>hint 模式内</td><td>依次写入输入缓冲，凑成完整标签即触发点击</td></tr><tr><td><code>Backspace</code></td><td>hint 模式内</td><td>删掉缓冲里最后一个字符</td></tr><tr><td><code>Esc</code> / <code>Q</code></td><td>hint 模式内</td><td>退出 hint 模式，不产生点击</td></tr><tr><td><code>W</code> <code>A</code> <code>S</code> <code>D</code></td><td>hint 模式内外均可</td><td>光标向上 / 左 / 下 / 右移动</td></tr><tr><td><code>H</code> <code>J</code> <code>K</code> <code>L</code></td><td>hint 模式内外均可</td><td>同上，Vim 习惯的另一组</td></tr><tr><td><code>Space</code></td><td>hint 模式内且光标已停在某目标上</td><td>点击光标所在元素</td></tr><tr><td>光标点击键（默认 <code>Space</code>）</td><td>hint 模式外且光标存在</td><td>点击光标所在元素</td></tr><tr><td>通知键（默认 <code>Space</code>）</td><td>hint 模式外且有 heads-up 通知</td><td>点开那条通知</td></tr></tbody></table><p>三个功能键的候选都是同一组：<code>Space</code>、<code>Enter</code>、<code>F</code>、<code>G</code>、<code>V</code>、<code>B</code>，设置页里点选即可，不需要改代码。默认还是 <code>F</code> 呼出、两个功能键都用 <code>Space</code>。</p><p>表里 hint 模式外的那几行有个共同前提：VimAct 这时接管按键。应用被加进<a href="/vimact-site/guide/settings.html">排除列表</a>，或者输入法正弹着，它就把按键整个交回去，触发键上屏是一个普通的字母，方向键也照原样交给当前 App。</p><h2 id="被保留的字母" tabindex="-1">被保留的字母 <a class="header-anchor" href="#被保留的字母" aria-label="Permalink to &quot;被保留的字母&quot;">​</a></h2><p>控制用的字母不当标签。分配标签时被排除的是这些：</p><ul><li><code>f</code> <code>q</code> — 任何时候都保留。<code>F</code> 呼出 / 退出标签层，<code>Q</code> 退出标签层；改了触发键也一样保留，手感不会突然变成一个标签字符。</li><li>触发键的字母 — 触发键选了 <code>G</code> / <code>V</code> / <code>B</code> 时再保留对应那个字母（选 <code>F</code> 已在上面）；选 <code>Space</code> 或 <code>Enter</code> 不额外占字母。</li><li><code>w</code> <code>a</code> <code>s</code> <code>d</code> — WASD 方向键开着时保留。</li><li><code>h</code> <code>j</code> <code>k</code> <code>l</code> — HJKL 方向键开着时保留。</li></ul><p>两组方向键都开着的默认状态下（触发键仍是 <code>F</code>），可用字符集剩下 16 个字母：<code>b c e g i m n o p r t u v x y z</code>。关掉其中一组方向键，对应四个字母就还给标签；触发键改成 <code>Space</code> / <code>Enter</code> 也不会把 <code>f</code> 还回来（<code>f</code> <code>q</code> 恒定保留），标签会更短。</p><h2 id="一次输入为什么不会误点" tabindex="-1">一次输入为什么不会误点 <a class="header-anchor" href="#一次输入为什么不会误点" aria-label="Permalink to &quot;一次输入为什么不会误点&quot;">​</a></h2><p>hint 模式下任何按键都被消费掉，这是模态的代价：<code>f</code> 打不出字母，空格不会真的空一格。好处是缓冲不会跟输入法串味。</p><p>输入满一个已存在的标签才动作。缓冲目前的内容如果不再是任何标签的前缀，缓冲立刻清零，等你重新输入。这套规则能保证命中，靠的是标签集合本身的前缀无关性，见 <a href="/vimact-site/guide/hints.html">Hint 标签点击</a>。</p>',12)])])}const u=e(a,[["render",i]]);export{m as __pageData,u as default};
